import atcoder/extra/monoid/monoid
import atcoder/extra/structure/compressed_range_fenwicktree_2d

proc addInt64(a, b: int64): int64 =
  a + b

proc zeroInt64(): int64 =
  0'i64

proc negateInt64(a: int64): int64 =
  -a

type
  AdditiveInt64Group =
    CommutativeGroupOf(
      int64,
      addInt64,
      zeroInt64,
      negateInt64,
    )

  Update = tuple[
    xLeft, xRight, yLower, yUpper: int,
    delta: int64
  ]

  Query = tuple[
    afterIndex, xLeft, xRight, yLower, yUpper: int,
    expected: int64
  ]

  PointCheck = tuple[
    afterIndex, x, y: int,
    expected: int64
  ]

