  (afterIndex: 1640, x: 17, y: -8, expected: -383'i64),
  (afterIndex: 1681, x: -257, y: -9, expected: -369'i64),
  (afterIndex: 1722, x: 65, y: -40, expected: -69'i64),
  (afterIndex: 1763, x: 31, y: 3, expected: -446'i64),
  (afterIndex: 1804, x: -11, y: -4, expected: -517'i64),
  (afterIndex: 1845, x: 6, y: 23, expected: -288'i64),
  (afterIndex: 1886, x: -10, y: -40, expected: 56'i64),
  (afterIndex: 1927, x: -4, y: -129, expected: 0'i64),
  (afterIndex: 1968, x: 12, y: -511, expected: -47'i64),
  (afterIndex: 2009, x: -21, y: 30, expected: 67'i64),
]

var tree =
  initCompressedRangeFenwickTree2D(
    registeredPoints,
    AdditiveInt64Group
  )

# Empty update uses deliberately unregistered coordinates.
tree.add(
  100001,
  100001,
  -100003,
  100007,
  17'i64
)

doAssert tree.sum(
  -10,
  10,
  -10,
  10
) == 0'i64

doAssert tree.get(
  12345,
  -12345
) == 0'i64

var queryIndex = 0
var pointIndex = 0

for updateIndex, update in updates:
  tree.add(
    update.xLeft,
    update.xRight,
    update.yLower,
    update.yUpper,
    update.delta
  )

  while queryIndex < queries.len and
      queries[queryIndex].afterIndex == updateIndex:
    let query =
      queries[queryIndex]

    doAssert tree.sum(
      query.xLeft,
      query.xRight,
      query.yLower,
      query.yUpper
    ) == query.expected

    inc queryIndex

  while pointIndex < pointChecks.len and
      pointChecks[pointIndex].afterIndex == updateIndex:
    let query =
      pointChecks[pointIndex]

    doAssert tree.get(
      query.x,
      query.y
    ) == query.expected

    inc pointIndex

doAssert queryIndex == queries.len
doAssert pointIndex == pointChecks.len

doAssert tree.sum(
  17,
  17,
  -9,
  22
) == 0'i64

doAssert tree.sum(
  -9,
  22,
  31,
  31
) == 0'i64

echo "COMPRESSED_RANGE_FENWICKTREE_2D_GROUP_ORACLE_OK queries=6144 points=50 stream=88075d0a5d841c827ff96a83ea2b3d1bacc56cb38660b8b472d4235659c28f3e"
